// Only text a caller once per window, even if they redial several times.
const store = $getWorkflowStaticData('global');
store.recentCallers = store.recentCallers || {};

const WINDOW_MS = 2 * 60 * 60 * 1000; // 2 hours
const now = Date.now();

// Forget anyone outside the window so the store cannot grow forever.
for (const [number, seenAt] of Object.entries(store.recentCallers)) {
  if (now - seenAt > WINDOW_MS) delete store.recentCallers[number];
}

const fresh = [];
for (const item of $input.all()) {
  const from = item.json.body?.From;
  if (!from) continue;
  if (store.recentCallers[from]) continue;
  store.recentCallers[from] = now;
  fresh.push(item);
}

return fresh;

