const BUSINESS_NAME = 'Your Company';
const TIMEZONE = 'America/Chicago';
const OPEN_HOUR = 8;   // 24h clock
const CLOSE_HOUR = 17; // 24h clock
const WORKDAYS = [1, 2, 3, 4, 5]; // 0 = Sunday
// -------------------------------------

const local = new Date(new Date().toLocaleString('en-US', { timeZone: TIMEZONE }));
const isOpen =
  WORKDAYS.includes(local.getDay()) &&
  local.getHours() >= OPEN_HOUR &&
  local.getHours() < CLOSE_HOUR;

return $input.all().map((item) => {
  const body = item.json.body || {};
  const fromNumber = body.From;
  const businessNumber = body.To;

  const smsBody = isOpen
    ? `Sorry we missed your call at ${BUSINESS_NAME} - we are on a job right now. Reply with your name, address and what is going on, and we will call you straight back. Reply STOP to opt out.`
    : `Thanks for calling ${BUSINESS_NAME}. We are closed right now and open again at ${OPEN_HOUR}:00. Reply with your name, address and the issue and you will be first in line in the morning. Reply STOP to opt out.`;

  const ownerAlert = `Missed call from ${fromNumber}\nStatus: ${body.DialCallStatus}\nHours: ${isOpen ? 'open' : 'after hours'}\nText-back sent.`;

  return { json: { fromNumber, businessNumber, smsBody, ownerAlert, isOpen } };
});
